PREFIX  gsp:  <http://www.opengis.net/ont/geosparql#>
PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>
PREFIX  dbprop: <http://dbpedia.org/property/>

SELECT  *
WHERE
  {   { ?city  rdfs:label  "Seoul"@en }
    UNION
      { ?alias  dbprop:redirect  ?city ;
                rdfs:label       "Seoul"@en
      }
    UNION
      { ?alias  dbprop:disambiguates  ?city ;
                rdfs:label            "Seoul"@en
      }
    OPTIONAL
      { ?city  dbpo:abstract  ?abstract }
    OPTIONAL
      { ?city  gsp:lat   ?latitude ;
               gsp:long  ?longitude
      }
    OPTIONAL
      { ?city  foaf:depiction  ?image }
    OPTIONAL
      { ?city  rdfs:label  ?name }
    OPTIONAL
      { ?city  foaf:homepage  ?home }
    OPTIONAL
      { ?city  dbpo:populationTotal  ?population }
    OPTIONAL
      { ?city  dbpo:thumbnail  ?thumbnail }
    FILTER langMatches(lang(?abstract), "sv")
  }", "PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  dbpr: <http://dbpedia.org/resource/>

SELECT  ?type
WHERE
  { dbpr:Database_dump
              rdf:type  ?type
  }", "PREFIX  dct:  <http://purl.org/dc/terms/>
PREFIX  dbpr: <http://dbpedia.org/resource/>

SELECT DISTINCT  ?category
WHERE
  { dbpr:Inge_Larsen
              dct:subject  ?category
  }", "PREFIX  dct:  <http://purl.org/dc/terms/>
PREFIX  dbpr: <http://dbpedia.org/resource/>

SELECT DISTINCT  ?category
WHERE
  { <http://dbpedia.org/resource/Unconquered_(1917_film)>
              dct:subject  ?category
  }", "PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  dbpr: <http://dbpedia.org/resource/>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>

SELECT DISTINCT  ?v
WHERE
  { VALUES ?v { dbpr:Psychodynamics dbpr:Jews dbpr:Evening dbpr:North_America dbpr:Importance dbpr:Sigmund_Freud dbpr:Eye_doctor dbpr:Long_Island dbpr:Psychotherapy dbpr:Committee dbpr:Armenia dbpr:Japan dbpr:Doctor_of_Medicine dbpr:Wednesday dbpr:Gender dbpr:Medicine dbpr:Utilization dbpr:Mereology <http://dbpedia.org/resource/1927_U.S._Open_(golf)> dbpr:Canada dbpr:February_7 dbpr:Supporter dbpr:Alfred_Adler dbpr:Psychology }
    ?v  rdf:type  foaf:Person
  }"]

