anchor_query:
PREFIX  dbpo: <http://dbpedia.org/ontology/>
PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  foaf: <http://xmlns.com/foaf/0.1/>
PREFIX  dbprop: <http://dbpedia.org/property/>

SELECT DISTINCT  ?Title ?Author ?NumberOfPages ?PubYear ?Abstract
WHERE
  { ?a     rdf:type            dbpo:Book ;
           dbpo:abstract       ?Abstract ;
           dbprop:pubDate      ?PubYear ;
           dbpo:numberOfPages  ?NumberOfPages ;
           rdfs:label          ?Title ;
           dbpo:author         ?name .
    ?name  foaf:name           ?Author
    FILTER ( ( ( lang(?Title) = "en" ) && ( lang(?Author) = "en" ) ) && ( lang(?Abstract) = "de" ) )
  }
